let draft=null;
function startBooking(){close();draft={id:uid(),guest:'',room:'',arrival:today(),departure:'',people:1,meal:'Nur Logis',status:'Bestätigt',rate:'',deposit:0};navigate('bookingDraft')}
function renderBookingDraft(){
 if(!draft){navigate('bookings');return}
 document.body.classList.add('reference-dashboard');$('main').innerHTML=bookingReference;
 const svg=$('main').querySelector('svg'), main=svg.querySelector('#main-view'), work=svg.querySelector('#workspace-view');
 const set=(g,x,y,v)=>{const t=g.querySelector('text[x="'+x+'"][y="'+y+'"]');if(t)t.textContent=v};
 const bind=(el,fn)=>{if(!el)return;el.setAttribute('tabindex','0');el.setAttribute('role','button');el.addEventListener('click',e=>{e.preventDefault();fn()});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}})};
 const date=v=>v?v.split('-').reverse().join('.'):'Auswählen';
 const opts=(items,v)=>'<option value="">Auswählen</option>'+items.map(x=>'<option value="'+esc(x[0])+'" '+(String(x[0])===String(v)?'selected':'')+'>'+esc(x[1])+'</option>').join('');
 const select=(k,items)=>'<select required name="'+k+'">'+opts(items,draft[k])+'</select>';
 const input=(k,type,extra='')=>'<input required name="'+k+'" type="'+type+'" value="'+esc(draft[k])+'" '+extra+'>';
 const meals=['Nur Logis','Frühstück','Halbpension','Vollpension'];
 function field(i){const forms=[select('guest',db.guests.map(g=>[g.id,g.name])), '<label>Anreise</label>'+input('arrival','date')+'<label>Abreise</label>'+input('departure','date'),'<label>Zimmer</label>'+select('room',db.rooms.filter(r=>r.status!=='Gesperrt').map(r=>[r.id,r.number+' · '+r.category]))+'<label>Personen</label>'+input('people','number','min="1" step="1"'),select('meal',meals.map(m=>[m,m])),'<label>Tarif pro Nacht CHF</label>'+input('rate','number','min="0" step="0.01"')+'<label>Vorgesehene Anzahlung CHF</label>'+input('deposit','number','min="0" step="0.01"')];dialog('<h2>'+['Gast','Anreise / Abreise','Zimmer / Personen','Verpflegung','Tarif / Anzahlung'][i]+'</h2><form id="draft-field">'+forms[i]+'<div class="actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">Übernehmen</button></div></form>');$('draft-field').onsubmit=e=>{e.preventDefault();const old=draft.room;new FormData(e.target).forEach((v,k)=>draft[k]=v);if(i===2&&old!==draft.room)draft.rate=get('rooms',draft.room).rate;close();renderBookingDraft()}}
 function persist(){try{if(!get('guests',draft.guest).id||!get('rooms',draft.room).id)throw Error('Gast und Zimmer auswählen');if(!Number.isFinite(nights(draft))||nights(draft)<=0||!Number.isInteger(Number(draft.people))||Number(draft.people)<1)throw Error('Aufenthalt oder Personenzahl ungültig');if(get('rooms',draft.room).status==='Gesperrt'||db.bookings.some(b=>b.room===draft.room&&active(b)&&overlap(b,draft)))throw Error('Zimmer nicht verfügbar: Doppelbuchung');if(draft.rate===''||!Number.isFinite(Number(draft.rate))||Number(draft.rate)<0||!Number.isFinite(Number(draft.deposit))||Number(draft.deposit)<0||Number(draft.deposit)>nights(draft)*Number(draft.rate))throw Error('Tarif oder Anzahlung ungültig');const old=JSON.stringify(db);try{db.bookings.push(Object.assign({},draft));log('Reservation erstellt')}catch(e){db=JSON.parse(old);throw e}draft=null;navigate('bookings')}catch(e){alert(e.message)}}
 const room=get('rooms',draft.room);
 [get('guests',draft.guest).name||'Gast auswählen',date(draft.arrival)+' – '+date(draft.departure),room.id?room.number+' · '+room.category+' · '+draft.people+' Personen':'Zimmer auswählen',draft.meal,draft.rate===''?'Tarif auswählen':money(draft.rate)+' / '+money(draft.deposit)].forEach((v,i)=>set(main,71,383+i*70,v));
 set(main,16,132,'Entwurf · '+db.hotel.name);set(work,16,132,'Entwurf · '+db.hotel.name);
 main.querySelectorAll('g[tabindex]').forEach((g,i)=>bind(g,()=>field(i)));
 const routes={'01-dashboard.svg':'dashboard','06-kalender.svg':'calendar','03-buchungen.svg':'bookings','09-rechnungen.svg':'invoices','19-menu.svg':'more','22-systemmeldungen.svg':'logs'};
 svg.querySelectorAll('a').forEach(a=>{const t=(a.querySelector('title')||{}).textContent,h=a.getAttribute('href');bind(a,()=>{if(t==='Reservation speichern')persist();else if(h==='#main-view'||h==='#workspace-view'){tab=h==='#main-view'?'overview':'work';renderBookingDraft()}else if(h==='08-suche.svg')$('search').click();else if(routes[h]){if(confirm('Entwurf verlassen?')){draft=null;navigate(routes[h])}}else if(h==='20-pdf-vollbild.svg')window.print();else field(3)})});
 work.querySelectorAll('g[tabindex]').forEach(g=>bind(g,()=>field(3)));main.setAttribute('display',tab==='work'?'none':'inline');work.setAttribute('display',tab==='work'?'inline':'none');
}


