let mealFilter='',mealOffset=0,mealDay=today();
function selectMealDay(){dialog('<h2>Verpflegungsdatum</h2><label>Datum</label><input id="meal-day" type="date" value="'+esc(mealDay)+'">'+btn('Schliessen','close'));$('meal-day').onchange=e=>{if(!e.target.value)return;mealDay=e.target.value;mealOffset=0;close();render()}}
function mealPrint(rows){const keys=['breakfast','lunch','dinner'];const totals=keys.map(k=>rows.reduce((n,x)=>n+(x[k]?Number(x.booking.people):0),0));document.body.classList.remove('reference-dashboard');$('main').innerHTML=card('<h1>Verpflegung · '+esc(mealDay)+'</h1><p>'+esc(db.hotel.name)+'</p><p>Frühstück: '+totals[0]+' · Mittagessen: '+totals[1]+' · Abendessen: '+totals[2]+'</p><table><thead><tr><th>Zimmer</th><th>Gast</th><th>Personen</th><th>F</th><th>M</th><th>A</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(get('rooms',x.booking.room).number)+'</td><td>'+esc(get('guests',x.booking.guest).name)+'</td><td>'+esc(x.booking.people)+'</td>'+keys.map(k=>'<td>'+esc(x[k]?x.booking.people:0)+'</td>').join('')+'</tr>').join('')+'</tbody></table><p>'+rows.length+' Reservationen</p><div class="actions no-print">'+btn('PDF / Drucken','print')+btn('Zurück','go','meals')+'</div>');}
function mealExport(rows){const safe=v=>{let t=String(v==null?'':v);if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};const data=[['Datum','Zimmer','Gast','Personen','Frühstück','Mittagessen','Abendessen']].concat(rows.map(x=>[mealDay,get('rooms',x.booking.room).number,get('guests',x.booking.guest).name,x.booking.people,...['breakfast','lunch','dinner'].map(k=>x[k]?x.booking.people:0)])).map(r=>r.map(safe).join(';')).join('\r\n');if(typeof Stay!=='undefined')Stay.share(data);else{const url=URL.createObjectURL(new Blob(['\ufeff',data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='verpflegung-'+mealDay+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function renderMealReference(){
 document.body.classList.add('reference-dashboard');$('main').innerHTML=mealReference;const svg=$('main').querySelector('svg'),m=svg.querySelector('#main-view'),w=svg.querySelector('#workspace-view'),plan=mealPlan(mealDay),keys=['breakfast','lunch','dinner'],names=['Frühstück','Mittagessen','Abendessen'];
 const set=(g,x,y,v)=>{const t=g.querySelector('text[x="'+x+'"][y="'+y+'"]');if(t)t.textContent=v};const bind=(el,fn)=>{if(!el)return;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.addEventListener('click',e=>{e.preventDefault();fn()});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}})};
 const count=k=>plan.reduce((n,x)=>n+(x[k]?Number(x.booking.people):0),0);
 const title=x=>get('rooms',x.booking.room).number+' · '+get('guests',x.booking.guest).name;
 const desc=x=>x.booking.meal+' · '+x.booking.people+' Pers.';
 const rows=plan.filter(x=>(!mealFilter||x[mealFilter])&&(title(x)+' '+desc(x)).toLowerCase().includes(query.toLowerCase()));
 const size=tab==='work'?3:7;if(mealOffset>=rows.length)mealOffset=0;const shown=rows.slice(mealOffset,mealOffset+size);
 const choose=k=>{mealFilter=mealFilter===k?'':k;mealOffset=0;renderMealReference()};
 const next=()=>{mealOffset=mealOffset+size>=rows.length?0:mealOffset+size;renderMealReference()};
 const print=()=>mealPrint(rows);
 const csv=()=>mealExport(rows);
 bind(m.querySelector('text[x="16"][y="130"]'),selectMealDay);set(w,16,130,mealDay.split('-').reverse().join('.')+' · Datum wählen');bind(w.querySelector('text[x="16"][y="130"]'),selectMealDay);
 const search=()=>{dialog('<h2>Verpflegung suchen</h2><input id="meal-query" value="'+esc(query)+'">'+btn('Schliessen','close'));$('meal-query').oninput=e=>{query=e.target.value;mealOffset=0;renderMealReference()}};
 keys.forEach((k,i)=>{set(m,74+i*121,204,count(k));set(w,40+i*110,316,count(k)+' '+names[i]);bind(m.querySelector('text[x="'+(74+i*121)+'"][y="204"]'),()=>choose(k))});
 set(m,16,130,mealDay.split('-').reverse().join('.')+' · '+plan.reduce((n,x)=>n+Number(x.booking.people),0)+' Hotelgäste');set(m,16,251,mealFilter?names[keys.indexOf(mealFilter)]+' · Zimmer / Gast':'Zimmer · Gast / Tarif');set(w,30,708,rows.length+' Einträge · Seite '+(Math.floor(mealOffset/size)+1)+' von '+Math.max(1,Math.ceil(rows.length/size)));set(w,30,741,'Ansicht: '+(mealFilter?names[keys.indexOf(mealFilter)]:'Alle'));set(w,42,411,query||'Suche nach Eintrag …');
 for(let i=0;i<7;i++){const x=shown[i];set(m,27,284+i*59,x?title(x):'–');set(m,27,303+i*59,x?desc(x):'');keys.forEach((k,j)=>set(m,282+j*33,297+i*59,x?(x[k]?'✓':'–'):''));bind(m.querySelector('text[x="27"][y="'+(284+i*59)+'"]'),()=>{if(x)edit('bookings',x.booking.id)})}
 for(let i=0;i<3;i++){const x=shown[i];set(w,42,498+i*67,x?title(x):'–');set(w,42,518+i*67,x?desc(x):'');bind(w.querySelector('text[x="42"][y="'+(498+i*67)+'"]'),()=>{if(x)edit('bookings',x.booking.id)})}
 svg.querySelectorAll('a').forEach(a=>{const h=a.getAttribute('href'),t=(a.querySelector('title')||{}).textContent;bind(a,()=>{if(t==='Zur Hauptübersicht')navigate('dashboard');else{tab=h==='#workspace-view'?'work':'overview';mealOffset=0;renderMealReference()}})});
 w.querySelectorAll('g[tabindex]').forEach((g,i)=>bind(g,()=>{if(i<3)choose(keys[i]);else search()}));bind(w.querySelector('text[x="42"][y="411"]'),search);bind(w.querySelector('text[x="240"][y="705"]'),print);bind(w.querySelector('text[x="311"][y="705"]'),csv);bind(m.querySelector('text[x="195"][y="755"]'),print);bind(w.querySelector('text[x="30"][y="708"]'),next);bind(m.querySelector('text[x="16"][y="702"]'),next);m.setAttribute('display',tab==='work'?'none':'inline');w.setAttribute('display',tab==='work'?'inline':'none')
}

render();window.addEventListener('resize',()=>{if(page==='dashboard'&&$('overlay').hidden)render()});